import { tv } from "tailwind-variants";

const separator = tv({
  base: "self-stretch bg-border data-[orientation=horizontal]:h-px data-[orientation=vertical]:w-px",
});

export { separator };

"use client";

import { Separator as BaseSeparator } from "@base-ui/react/separator";

import { mergeVariantClassName } from "@/registry/sector23/lib/merge-base-ui";

import { separator } from "./separator.style";

function Separator({ className, ...props }: BaseSeparator.Props) {
  return (
    <BaseSeparator
      data-slot="separator"
      className={mergeVariantClassName(separator, {}, className)}
      {...props}
    />
  );
}

export { Separator };
